import{_ as r,a0 as a,w as i,s,ao as d,I as e,x as o,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"OpenBoard：面向教育工作者的開源交互式白板 | LCTT x X-CMD","titleTemplate":false,"description":"OpenBoard：面向教育工作者的開源交互式白板 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OpenBoard：面向教育工作者的開源交互式白板 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OpenBoard：面向教育工作者的開源交互式白板 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220118 OpenBoard- An Open Source Interactive Whiteboard for Educators","title":"OpenBoard：面向教育工作者的開源交互式白板","tag":"202201","desc":""},"relativePath":"202201/20220118 OpenBoard- An Open Source Interactive Whiteboard for Educators.md","filePath":"[post].md"}'),u={name:"202201/20220118 OpenBoard- An Open Source Interactive Whiteboard for Educators.md"};function m(f,t,b,O,B,x){const l=a("Link");return i(),s("div",null,[t[21]||(t[21]=d('<h1 id="openboard-面向教育工作者的開源交互式白板" tabindex="-1">OpenBoard：面向教育工作者的開源交互式白板 <a class="header-anchor" href="#openboard-面向教育工作者的開源交互式白板" aria-label="Permalink to “OpenBoard：面向教育工作者的開源交互式白板”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202201/25/134634wzn22l0x3zycy9et.jpg" alt=""></p><blockquote><p>OpenBoard 是為中小學和大學定製的交互式開源白板。讓我們來看看它提供了什麼。</p></blockquote><p>有幾個可用於教育的開源工具，但是，並非所有這些面向中小學和大學的軟件都能達到商業軟件級的良好維護。</p><p>OpenBoard 就是這樣一個不同凡響的自由開源工具，它可以不打折扣地為教育服務。它是一個交互式白板程序，具有所有基本功能，並支持各種硬件。</p><h3 id="openboard-自由及開源的交互式白板" tabindex="-1">OpenBoard：自由及開源的交互式白板 <a class="header-anchor" href="#openboard-自由及開源的交互式白板" aria-label="Permalink to “OpenBoard：自由及開源的交互式白板”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/openboard-screenshot.png?resize=800%2C435&amp;ssl=1" alt=""></p><p>作為一個自由開源的程序，OpenBoard 看起來是一個令人印象深刻的選擇。</p><p>瑞士日內瓦州的教育部門（DIP）與 GitHub 上的社區一起維護該工具。</p><p>通過交互式白板促進簡單的數字教學不應該花費很多，這就是 OpenBoard 的優勢所在。</p><p>它提供的一系列功能對大多數中小學和大學來説應該是足夠的。</p><p>雖然我無法在中小學/大學環境中測試它，但我會重點介紹它提供的主要功能。</p><h3 id="openboard-的特點" tabindex="-1">OpenBoard 的特點 <a class="header-anchor" href="#openboard-的特點" aria-label="Permalink to “OpenBoard 的特點”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/openboard-screenshot-1.png?resize=800%2C462&amp;ssl=1" alt=""></p><p>交互式白板沒有眾多花哨的功能，但足以使教師能夠儘可能輕鬆地表達自己。</p><p>我注意到的一些特點包括：</p><ul><li>跨平台支持</li><li>能夠自由地寫寫畫畫</li><li>能夠添加註釋</li><li>能夠刪除註釋</li><li>可以使用熒光筆高亮顯示你的白板的部分區域</li><li>單獨互動和移動創建/繪製的項目</li><li>按順序添加多個頁面，可以繼續教學而不需要擦除</li><li>能夠在頁面間滾動瀏覽</li><li>繪製線條（從三種不同線寬中選擇）</li><li>切換手寫筆模式（如果你使用的是手寫板或類似的東西）</li><li>輕鬆擦除在白板上創建的項目</li><li>可以從一組不同的背景中選擇，包括把它變成黑板或帶網格線的背景</li><li>各種必要的應用，包括計算器、地圖、尺子等，都可以通過拖放使用</li><li>提供的一些形狀，可以使繪圖更容易</li><li>能夠向你的白板添加音頻/視頻，並無縫播放，以獲得更好的體驗</li><li>虛擬激光筆</li><li>可放大和縮小</li><li>書寫文字，調整大小，並克隆它</li><li>從白板中對屏幕進行截圖</li><li>需要時可使用虛擬鍵盤</li></ul><p>在我簡短的測試中，用户界面和可用的選項工作得非常好，沒有任何故障。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/openboard-dock.png?resize=800%2C344&amp;ssl=1" alt=""></p><p>當然，你的體驗將取決於設備的類型和你的設置。你可以用 Wacom 平板、雙顯示器設置，或者通過支持觸摸的筆記本電腦使用投影儀來嘗試。</p><h3 id="在-linux-中安裝-openboard" tabindex="-1">在 Linux 中安裝 OpenBoard <a class="header-anchor" href="#在-linux-中安裝-openboard" aria-label="Permalink to “在 Linux 中安裝 OpenBoard”">​</a></h3><p>更好的是，它可以在多個平台上使用，包括 Windows、macOS 和 Linux。</p>',22)),e("p",null,[t[2]||(t[2]=o("如果你使用的是 Ubuntu，你可以到官方網站下載 DEB 文件。另外對於其他 Linux 發行版，你可以選擇通過 ",-1)),n(l,{href:"https://flathub.org/apps/details/ch.openboard.OpenBoard"},{default:p(()=>[...t[0]||(t[0]=[o("Flathub",-1)])]),_:1}),t[3]||(t[3]=o()),n(l,{href:"https://itsfoss.com/flatpak-guide/"},{default:p(()=>[...t[1]||(t[1]=[o("安裝 Flatpak 軟件包",-1)])]),_:1}),t[4]||(t[4]=o("。",-1))]),e("ul",null,[e("li",null,[n(l,{href:"https://www.openboard.ch/index.en.html"},{default:p(()=>[...t[5]||(t[5]=[o("OpenBoard",-1)])]),_:1})])]),t[22]||(t[22]=e("h3",{id:"結語",tabindex:"-1"},[o("結語 "),e("a",{class:"header-anchor",href:"#結語","aria-label":"Permalink to “結語”"},"​")],-1)),t[23]||(t[23]=e("p",null,"總的來説，我發現它在使用和導航方面毫不費力。你可以在多個頁面之間快速切換，無縫擦除/添加項目，同時還可以在白板上添加豐富的元素。",-1)),t[24]||(t[24]=e("p",null,"通過虛擬激光筆以及一些應用，使得它適合在各種中小學和大學中使用而沒有任何障礙。",-1)),t[25]||(t[25]=e("p",null,"我不知道它是否可以被稱為谷歌課堂或 Miro 白板功能的替代品，但對於更簡單的使用，OpenBoard 可以勝任。",-1)),t[26]||(t[26]=e("p",null,"如果你還沒有試過，我建議你試一試。你知道有什麼比這更好的東西嗎？請在下面的評論中告訴我。",-1)),t[27]||(t[27]=e("hr",null,null,-1)),e("p",null,[t[7]||(t[7]=o("via: ",-1)),n(l,{href:"https://itsfoss.com/openboard/"},{default:p(()=>[...t[6]||(t[6]=[o("https://itsfoss.com/openboard/",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=o("作者：",-1)),n(l,{href:"https://itsfoss.com/author/ankush/"},{default:p(()=>[...t[8]||(t[8]=[o("Ankush Das",-1)])]),_:1}),t[13]||(t[13]=o(" 選題：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[9]||(t[9]=[o("lujun9972",-1)])]),_:1}),t[14]||(t[14]=o(" 譯者：",-1)),n(l,{href:"https://github.com/geekpi"},{default:p(()=>[...t[10]||(t[10]=[o("geekpi",-1)])]),_:1}),t[15]||(t[15]=o(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=o("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[o("LCTT",-1)])]),_:1}),t[19]||(t[19]=o(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[o("Linux中國",-1)])]),_:1}),t[20]||(t[20]=o(" 榮譽推出",-1))])])}const C=r(u,[["render",m]]);export{h as __pageData,C as default};
